:root {
      --primary: #0f4c81;
      --accent: #f97316;
      --bg-grad-top: #e8eef3;
      --bg-grad-bot: #cfd8e3;
      --card-bg: rgba(255, 255, 255, 0.96);
      --text-main: #1e293b;
      --text-muted: #64748b;
    }

    * { box-sizing: border-box; margin: 0; padding: 0; user-select: none; -webkit-user-select: none; }
    body {
      font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
      background: #0f172a;
      display: flex;
      justify-content: center;
      align-items: center;
      min-height: 100vh;
    }

    /* Contenedor Vertical (9:16 móvil) */
    #app-container {
      position: relative;
      width: 100%;
      max-width: 440px;
      height: 100vh;
      max-height: 860px;
      background: linear-gradient(180deg, var(--bg-grad-top) 0%, var(--bg-grad-bot) 100%);
      overflow: hidden;
      display: flex;
      flex-direction: column;
      box-shadow: 0 20px 50px rgba(0,0,0,0.5);
    }

    @media (min-width: 480px) {
      #app-container { height: 92vh; border-radius: 28px; border: 6px solid #334155; }
    }

    #app-container:fullscreen, #app-container:-webkit-full-screen {
      max-width: 100%; max-height: 100%; width: 100vw; height: 100vh; border-radius: 0; border: none;
    }

    /* Cabecera unificada superior */
    .header {
      position: absolute; top: 0; left: 0; right: 0;
      padding: 12px 16px;
      display: flex; justify-content: space-between; align-items: center;
      z-index: 20; pointer-events: none;
    }
    .header-left, .header-right {
      display: flex; gap: 6px; align-items: center; pointer-events: auto;
    }

    .icon-btn {
      width: 36px; height: 36px; border-radius: 10px; border: 1px solid rgba(0,0,0,0.08);
      background: rgba(255,255,255,0.92); backdrop-filter: blur(6px);
      display: flex; justify-content: center; align-items: center;
      cursor: pointer; box-shadow: 0 2px 8px rgba(0,0,0,0.08);
      transition: all 0.2s; color: var(--text-main); font-weight: 700; font-size: 0.75rem;
    }
    .icon-btn.active { background: var(--accent); color: #fff; border-color: var(--accent); }
    .icon-btn:active { transform: scale(0.94); }

    .pill-btn {
      padding: 7px 11px; border-radius: 20px; border: 1px solid rgba(0,0,0,0.08);
      background: rgba(255,255,255,0.92); backdrop-filter: blur(6px);
      font-size: 0.72rem; font-weight: 700;
      color: var(--text-main); cursor: pointer; box-shadow: 0 2px 8px rgba(0,0,0,0.08);
      transition: all 0.2s; display: flex; align-items: center; gap: 4px;
    }
    .pill-btn:hover { background: #fff; }
    .pill-btn.active { background: var(--primary); color: white; border-color: var(--primary); }

    /* Lienzo 3D y Capa de Líneas Guía */
    #viewport { position: relative; flex: 1; width: 100%; height: 100%; overflow: hidden; }
    canvas { width: 100% !important; height: 100% !important; display: block; outline: none; }

    #callout-svg {
      position: absolute; top: 0; left: 0; width: 100%; height: 100%;
      pointer-events: none; z-index: 10;
    }
    #pins-layer {
      position: absolute; top: 0; left: 0; width: 100%; height: 100%;
      pointer-events: none; z-index: 12;
    }

    /* Pines Numerados */
    .pin {
      position: absolute; width: 28px; height: 28px; margin-left: -14px; margin-top: -14px;
      border-radius: 50%; background: #ffffff; color: var(--text-main);
      font-weight: 700; font-size: 0.78rem;
      display: flex; justify-content: center; align-items: center;
      box-shadow: 0 3px 10px rgba(0,0,0,0.22);
      border: 2px solid #cbd5e1;
      cursor: pointer; pointer-events: auto;
      transition: transform 0.2s, background 0.2s, color 0.2s, border-color 0.2s;
    }
    .pin:hover { transform: scale(1.1); }
    .pin.active {
      background: var(--accent); color: #fff; border-color: #fff;
      transform: scale(1.22);
      box-shadow: 0 0 0 4px rgba(249, 115, 22, 0.35), 0 4px 12px rgba(0,0,0,0.3);
      z-index: 15;
    }

    /* Punto de anclaje sobre la máquina */
    .anchor-dot {
      position: absolute; width: 8px; height: 8px; margin-left: -4px; margin-top: -4px;
      border-radius: 50%; background: var(--primary); border: 2px solid #fff;
      box-shadow: 0 1px 4px rgba(0,0,0,0.4); pointer-events: none;
    }
    .anchor-dot.active { background: var(--accent); transform: scale(1.3); }

    /* Tarjeta Inferior */
    .bottom-area {
      position: absolute; bottom: 0; left: 0; right: 0;
      padding: 8px 12px 12px;
      display: flex; flex-direction: column; gap: 5px;
      z-index: 25; pointer-events: none;
    }
    .info-card {
      background: var(--card-bg); backdrop-filter: blur(12px);
      border-radius: 16px; padding: 11px 13px;
      box-shadow: 0 8px 30px rgba(0,0,0,0.16);
      border: 1px solid rgba(255,255,255,0.8);
      pointer-events: auto;
      display: flex; flex-direction: column; gap: 6px;
    }

    .card-top-row {
      display: flex; justify-content: space-between; align-items: center; gap: 8px;
    }
    .info-card h2 {
      font-size: 0.94rem; color: var(--primary); font-weight: 800; line-height: 1.2;
    }

    .info-capsule {
      display: flex; align-items: center; gap: 8px;
      background: #f1f5f9; border-radius: 12px; padding: 6px 9px;
      border: 1px solid rgba(0,0,0,0.03);
    }
    .capsule-icon {
      width: 28px; height: 28px; border-radius: 50%; background: #ffffff;
      display: flex; justify-content: center; align-items: center;
      font-size: 0.82rem; box-shadow: 0 2px 5px rgba(0,0,0,0.05); flex-shrink: 0;
    }
    .capsule-content { display: flex; flex-direction: column; width: 100%; }
    .capsule-label {
      font-size: 0.60rem; font-weight: 700; color: var(--text-muted);
      text-transform: uppercase; letter-spacing: 0.4px; margin-bottom: 0px;
    }
    .capsule-text {
      font-size: 0.74rem; font-weight: 400; color: var(--text-main); line-height: 1.2;
    }

    .anim-btn {
      background: var(--accent); color: white; border: none;
      padding: 6px 12px; border-radius: 14px; font-weight: 700;
      font-size: 0.7rem; letter-spacing: 0.5px; cursor: pointer;
      box-shadow: 0 3px 10px rgba(249, 115, 22, 0.35);
      transition: all 0.2s; white-space: nowrap; flex-shrink: 0;
    }
    .anim-btn.playing { background: #dc2626; box-shadow: 0 3px 10px rgba(220, 38, 38, 0.4); }
    .anim-btn:active { transform: scale(0.95); }

    .stepper {
      align-self: center; display: flex; align-items: center;
      background: rgba(255,255,255,0.95); border-radius: 10px;
      box-shadow: 0 4px 15px rgba(0,0,0,0.12); overflow: hidden;
      pointer-events: auto; border: 1px solid rgba(0,0,0,0.06);
    }
    .stepper button {
      background: transparent; border: none; width: 36px; height: 28px;
      font-size: 0.9rem; font-weight: bold; color: var(--text-main);
      cursor: pointer; transition: background 0.15s;
    }
    .stepper button:hover { background: #f1f5f9; }
    .stepper span {
      padding: 0 12px; font-size: 0.78rem; font-weight: 700; color: var(--text-main);
      border-left: 1px solid #e2e8f0; border-right: 1px solid #e2e8f0;
    }

    #loading-screen {
      position: absolute; inset: 0; background: rgba(15, 23, 42, 0.92);
      backdrop-filter: blur(8px); z-index: 50;
      display: flex; flex-direction: column; justify-content: center; align-items: center;
      color: white; text-align: center; padding: 30px;
      transition: opacity 0.4s ease;
    }
    #loading-screen.hidden { opacity: 0; pointer-events: none; }
    .loader-spinner {
      width: 44px; height: 44px; border: 4px solid rgba(255,255,255,0.2);
      border-top-color: var(--accent); border-radius: 50%;
      animation: spin 0.9s linear infinite; margin-bottom: 14px;
    }
    @keyframes spin { to { transform: rotate(360deg); } }
    .loader-text { font-size: 0.88rem; font-weight: 600; color: #cbd5e1; }

