import * as THREE from 'three';
  import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
  import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';

  const PARTS_DATA = [
    {
      id: 1,
      name: "Cabezal y eje principal",
      nodeName: "Headstock_Group",
      anchor3D: new THREE.Vector3(-1.15, 1.55, 0.20),
      loc: "Extremo izquierdo de la máquina",
      func: "Sostiene el plato y lo hace girar con la pieza.",
      animClip: "Operation_Basic",
      camPos: new THREE.Vector3(-2.2, 2.6, 2.8),
      camTargetOffset: new THREE.Vector3(0, -0.10, 0)
    },
    {
      id: 2,
      name: "Plato (mandril)",
      nodeName: "Chuck",
      anchor3D: new THREE.Vector3(-0.56, 1.43, 0.14),
      loc: "Al frente del cabezal",
      func: "Sujeta la pieza (material base) que se va a trabajar.",
      animClip: "Idle_Chuck",
      camPos: new THREE.Vector3(-0.45, 1.9, 1.7),
      camTargetOffset: new THREE.Vector3(0, -0.18, 0)
    },
    {
      id: 3,
      name: "Bancada",
      nodeName: "Bed_Ways",
      anchor3D: new THREE.Vector3(-0.30, 1.06, 0.15),
      loc: "Base larga de la máquina",
      func: "Sobre ella se deslizan los carros y el contrapunto.",
      animClip: "Carriage_Move",
      camPos: new THREE.Vector3(0.0, 1.9, 2.6),
      camTargetOffset: new THREE.Vector3(0, -0.15, 0)
    },
    {
      id: 4,
      name: "Carro transversal",
      nodeName: "CrossSlide_Group",
      anchor3D: new THREE.Vector3(0.12, 1.22, 0.18),
      loc: "Sobre la bancada, al frente",
      func: "Acerca o aleja la herramienta de la pieza.",
      animClip: "CrossSlide_Move",
      camPos: new THREE.Vector3(0.38, 1.85, 1.6),
      camTargetOffset: new THREE.Vector3(0, -0.22, 0)
    },
    {
      id: 5,
      name: "Charriot (carro superior o auxiliar)",
      nodeName: "Compound_Group",
      anchor3D: new THREE.Vector3(0.12, 1.35, -0.02),
      loc: "Sobre el carro transversal",
      func: "Mueve la cuchilla para dar la forma deseada a la pieza.",
      animClip: "Operation_Basic",
      camPos: new THREE.Vector3(0.32, 1.9, 1.4),
      camTargetOffset: new THREE.Vector3(0, -0.25, 0)
    },
    {
      id: 6,
      name: "Husillo transversal",
      nodeName: "CrossSlide_Handwheel",
      anchor3D: new THREE.Vector3(0.12, 1.21, 0.44),
      loc: "Volante del carro transversal",
      func: "Tornillo que mueve el carro transversal con precisión milimétrica.",
      animClip: "CrossSlide_Move",
      camPos: new THREE.Vector3(0.38, 1.75, 1.55),
      camTargetOffset: new THREE.Vector3(0, -0.18, 0)
    },
    {
      id: 7,
      name: "Torreta portaherramientas y su llave",
      nodeName: "Toolpost_Group",
      anchor3D: new THREE.Vector3(0.105, 1.52, 0.0),
      loc: "Sobre el charriot",
      func: "Sostiene la herramienta de corte.",
      animClip: "Operation_Basic",
      camPos: new THREE.Vector3(0.28, 1.95, 1.35),
      camTargetOffset: new THREE.Vector3(0, -0.25, 0)
    },
    {
      id: 8,
      name: "Delantal",
      nodeName: "Carriage_Group",
      anchor3D: new THREE.Vector3(0.12, 0.88, 0.45),
      loc: "Bajo el carro principal, al frente",
      func: "Caja con los mandos de avance y roscado. Tiene un dispositivo que impide usar ambos a la vez.",
      animClip: "Carriage_Move",
      camPos: new THREE.Vector3(0.2, 1.4, 1.7),
      camTargetOffset: new THREE.Vector3(0, -0.15, 0)
    },
    {
      id: 9,
      name: "Caja de avances y lira",
      nodeName: "Front_Rods_Group",
      anchor3D: new THREE.Vector3(-0.75, 0.91, 0.36),
      loc: "Debajo del cabezal, a la izquierda",
      func: "Permiten elegir distintos avances y pasos de rosca sin cambiar engranes a cada rato.",
      animClip: "Handwheels_Rotate",
      camPos: new THREE.Vector3(-0.5, 1.45, 1.8),
      camTargetOffset: new THREE.Vector3(0, -0.18, 0)
    },
    {
      id: 10,
      name: "Contrapunto",
      nodeName: "Tailstock_Group",
      anchor3D: new THREE.Vector3(1.16, 1.42, 0.05),
      loc: "Extremo derecho de la máquina",
      func: "Apoya el otro extremo de piezas largas o pesadas.",
      animClip: "Tailstock_Move",
      camPos: new THREE.Vector3(1.45, 1.8, 1.7),
      camTargetOffset: new THREE.Vector3(0, -0.22, 0)
    }
  ];

  const viewport = document.getElementById('viewport');
  const svgLayer = document.getElementById('callout-svg');
  const pinsLayer = document.getElementById('pins-layer');

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(42, viewport.clientWidth / viewport.clientHeight, 0.1, 50);

  const DEFAULT_CAM_POS = new THREE.Vector3(2.3, 2.35, 3.6);
  const DEFAULT_CAM_TARGET = new THREE.Vector3(0.0, 0.95, 0.0);
  camera.position.copy(DEFAULT_CAM_POS);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(viewport.clientWidth, viewport.clientHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.15;
  viewport.appendChild(renderer.domElement);

  const controls = new OrbitControls(camera, renderer.domElement);
  controls.target.copy(DEFAULT_CAM_TARGET);
  controls.enableDamping = true;
  controls.dampingFactor = 0.06;
  controls.maxPolarAngle = Math.PI / 2 + 0.08;
  controls.minDistance = 1.0;
  controls.maxDistance = 8.0;

  scene.add(new THREE.HemisphereLight(0xffffff, 0x94a3b8, 1.6));
  const dirLight1 = new THREE.DirectionalLight(0xffffff, 2.2);
  dirLight1.position.set(4, 6, 5);
  scene.add(dirLight1);

  const dirLight2 = new THREE.DirectionalLight(0xdbeafe, 1.2);
  dirLight2.position.set(-4, 3, -3);
  scene.add(dirLight2);

  let latheRoot = null;
  let mixer = null;
  let animationsMap = {};
  let currentAction = null;
  let currentPartIndex = 0;
  let isExploded = false;
  let pinsVisible = true;
  let camAnim = null;

  const pinElements = [];
  PARTS_DATA.forEach((part, idx) => {
    const pin = document.createElement('div');
    pin.className = 'pin';
    pin.textContent = part.id;
    pin.addEventListener('click', (e) => {
      e.stopPropagation();
      selectPart(idx, true);
    });
    pinsLayer.appendChild(pin);

    const dot = document.createElement('div');
    dot.className = 'anchor-dot';
    pinsLayer.appendChild(dot);

    const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
    svgLayer.appendChild(line);

    pinElements.push({ pin, dot, line, part });
  });

  const originalMaterials = new Map();

  function highlightNode(targetNodeName) {
    if (!latheRoot) return;
    originalMaterials.forEach((mat, mesh) => { mesh.material = mat; });

    const targetNode = latheRoot.getObjectByName(targetNodeName);
    if (!targetNode) return;

    targetNode.traverse((child) => {
      if (child.isMesh) {
        const clonedMat = child.material.clone();
        clonedMat.emissive = new THREE.Color(0xf97316);
        clonedMat.emissiveIntensity = 0.38;
        child.material = clonedMat;
      }
    });
  }

  function selectPart(index, flyCamera = true) {
    currentPartIndex = (index + PARTS_DATA.length) % PARTS_DATA.length;
    const part = PARTS_DATA[currentPartIndex];

    document.getElementById('part-title').textContent = `${part.id}. ${part.name}`;
    document.getElementById('part-loc').textContent = part.loc;
    document.getElementById('part-func').textContent = part.func;
    document.getElementById('step-counter').textContent = `${part.id} / ${PARTS_DATA.length}`;

    pinElements.forEach((item, idx) => {
      const isSelected = idx === currentPartIndex;
      item.pin.classList.toggle('active', isSelected);
      item.dot.classList.toggle('active', isSelected);

      if (isSelected) {
        item.line.setAttribute('stroke', '#f97316');
        item.line.setAttribute('stroke-width', '2.8');
        item.line.removeAttribute('stroke-dasharray');
      } else {
        item.line.setAttribute('stroke', '#94a3b8');
        item.line.setAttribute('stroke-width', '1.4');
        item.line.setAttribute('stroke-dasharray', '4, 4');
      }
    });

    highlightNode(part.nodeName);
    stopCurrentAnimation();

    if (flyCamera && !isExploded && latheRoot) {
      const node = latheRoot.getObjectByName(part.nodeName);
      let center = part.anchor3D.clone();
      if (node) {
        const box = new THREE.Box3().setFromObject(node);
        box.getCenter(center);
      }

      const finalTarget = center.clone().add(part.camTargetOffset);
      const finalPos = part.camPos.clone().add(part.camTargetOffset);

      animateCameraTo(finalPos, finalTarget);
    }
  }

  function animateCameraTo(targetPos, targetLook) {
    camAnim = {
      startPos: camera.position.clone(),
      endPos: targetPos.clone(),
      startLook: controls.target.clone(),
      endLook: targetLook.clone(),
      progress: 0
    };
  }

  const btnAnim = document.getElementById('btn-anim');
  function stopCurrentAnimation() {
    if (currentAction) {
      currentAction.fadeOut(0.25);
      currentAction = null;
    }
    btnAnim.textContent = 'ANIMAR';
    btnAnim.classList.remove('playing');
  }

  btnAnim.addEventListener('click', () => {
    if (!mixer) return;
    const part = PARTS_DATA[currentPartIndex];
    const clip = animationsMap[part.animClip];
    if (!clip) return;

    if (currentAction) {
      stopCurrentAnimation();
      return;
    }

    if (isExploded) toggleExplodedView(false);

    const action = mixer.clipAction(clip);
    action.reset();
    action.setLoop(THREE.LoopRepeat, Infinity);
    action.fadeIn(0.25).play();
    currentAction = action;

    btnAnim.textContent = 'DETENER';
    btnAnim.classList.add('playing');
  });

  const btnExplode = document.getElementById('btn-explode');
  function toggleExplodedView(forceState) {
    if (!mixer) return;
    isExploded = forceState !== undefined ? forceState : !isExploded;
    btnExplode.classList.toggle('active', isExploded);

    stopCurrentAnimation();
    mixer.stopAllAction();

    const clipName = isExploded ? 'Exploded_View' : 'Exploded_Reset';
    const clip = animationsMap[clipName];
    if (clip) {
      const action = mixer.clipAction(clip);
      action.reset();
      action.setLoop(THREE.LoopOnce, 1);
      action.clampWhenFinished = true;
      action.play();
    }

    if (isExploded) {
      animateCameraTo(new THREE.Vector3(2.5, 2.6, 3.9), new THREE.Vector3(0, 1.15, 0));
    } else {
      animateCameraTo(DEFAULT_CAM_POS, DEFAULT_CAM_TARGET);
    }
  }
  btnExplode.addEventListener('click', () => toggleExplodedView());

  const btnTogglePins = document.getElementById('btn-toggle-pins');
  btnTogglePins.addEventListener('click', () => {
    pinsVisible = !pinsVisible;
    pinsLayer.style.display = pinsVisible ? 'block' : 'none';
    svgLayer.style.display = pinsVisible ? 'block' : 'none';
    btnTogglePins.classList.toggle('active', !pinsVisible);
  });

  document.getElementById('btn-reset-cam').addEventListener('click', () => {
    animateCameraTo(DEFAULT_CAM_POS, DEFAULT_CAM_TARGET);
  });

  const appContainer = document.getElementById('app-container');
  document.getElementById('btn-fullscreen').addEventListener('click', () => {
    if (!document.fullscreenElement) {
      appContainer.requestFullscreen?.() || appContainer.webkitRequestFullscreen?.();
    } else {
      document.exitFullscreen?.() || document.webkitExitFullscreen?.();
    }
  });

  document.getElementById('btn-prev').addEventListener('click', () => selectPart(currentPartIndex - 1, true));
  document.getElementById('btn-next').addEventListener('click', () => selectPart(currentPartIndex + 1, true));

  const loader = new GLTFLoader();
  const loadingScreen = document.getElementById('loading-screen');

  const MODEL_URL = VIEWER_CONFIG.modelo.url;

  loader.load(
    MODEL_URL,
    (gltf) => {
      latheRoot = gltf.scene;
      scene.add(latheRoot);

      originalMaterials.clear();
      latheRoot.traverse((child) => {
        if (child.isMesh) originalMaterials.set(child, child.material);
      });

      mixer = new THREE.AnimationMixer(latheRoot);
      animationsMap = {};
      gltf.animations.forEach((clip) => { animationsMap[clip.name] = clip; });

      loadingScreen.classList.add('hidden');
      selectPart(0, false);
    },
    (xhr) => {
      if (xhr.lengthComputable) {
        const percent = Math.round((xhr.loaded / xhr.total) * 100);
        document.querySelector('.loader-text').textContent = `Cargando Torno 3D... ${percent}%`;
      }
    },
    (error) => {
      console.error('Error al cargar el modelo 3D:', error);
      document.querySelector('.loader-text').textContent = 'Error al cargar el modelo desde GitHub.';
    }
  );

  // --- DISTRIBUCIÓN RESPONSIVE OPTIMIZADA PARA MÓVIL (Márgenes y separación de pines) ---
  function updateCallouts() {
    if (!latheRoot || !pinsVisible) return;
    const width = viewport.clientWidth;
    const height = viewport.clientHeight;
    const totalPins = pinElements.length;

    pinElements.forEach((item, idx) => {
      const worldPos = item.part.anchor3D.clone();
      const node = latheRoot.getObjectByName(item.part.nodeName);
      if (node) {
        const box = new THREE.Box3().setFromObject(node);
        box.getCenter(worldPos);
      }

      const projected = worldPos.clone().project(camera);
      const ax = (projected.x * 0.5 + 0.5) * width;
      const ay = (-(projected.y * 0.5) + 0.5) * height;

      item.dot.style.left = `${ax}px`;
      item.dot.style.top = `${ay}px`;

      // Márgenes laterales adaptados para dispositivos móviles (evita que seamontonen en los extremos)
      const marginX = 16;
      const usableW = width - (marginX * 2);
      const ratio = idx / Math.max(1, totalPins - 1);

      const px = marginX + (ratio * usableW);
      // Altura escalonada limpia en la franja superior
      const py = 112 + (idx % 2) * 25;

      item.pin.style.left = `${px}px`;
      item.pin.style.top = `${py}px`;

      item.line.setAttribute('x1', ax);
      item.line.setAttribute('y1', ay);
      item.line.setAttribute('x2', px);
      item.line.setAttribute('y2', py);
    });
  }

  const clock = new THREE.Clock();
  function animate() {
    requestAnimationFrame(animate);
    const delta = clock.getDelta();

    if (mixer) mixer.update(delta);

    if (camAnim) {
      camAnim.progress += delta * 2.2;
      const t = Math.min(1, camAnim.progress);
